  "summary": "The code contained critical security and performance flaws, primarily due to an unvalidated proxy endpoint that allowed SSRF and memory exhaustion. The refactored code introduces strict URL allowlisting, request timeouts, streaming responses, and proper error handling to ensure robustness.",
  "fixed_code": "const express = require('express');\nconst fetch = require('node-fetch');\nconst app = express();\n\nconst ALLOWED_DOMAINS = ['trusted-api.com', 'example.com'];\n\n/**\n * Proxies requests to external URLs after validation.\n * @param {string} url - The target URL to fetch.\n */\napp.get('/fetch-data', async (req, res) => {\n    const targetUrl = req.query.url;\n    if (!targetUrl) return res.status(400).send('URL is required');\n\n    try {\n        const parsedUrl = new URL(targetUrl);\n        if (!ALLOWED_DOMAINS.includes(parsedUrl.hostname)) {\n            return res.status(403).send('Domain not allowed');\n        }\n\n        const controller = new AbortController();\n        const timeout = setTimeout(() => controller.abort(), 5000);\n\n        const response = await fetch(targetUrl, { signal: controller.signal });\n        clearTimeout(timeout);\n\n        if (!response.ok) throw new Error('Fetch failed');\n\n        res.setHeader('Content-Type', 'text/plain');\n        response.body.pipe(res);\n    } catch (err) {\n        res.status(500).send('Error fetching data');\n    }\n});\n\napp.listen(process.env.PORT || 3000);"
}
